using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF 9 renamed "Discriminator" to "$type".
            // Existing documents use "Discriminator", so preserve it.
            entity.HasDiscriminator().HasValue("Blog");
            entity.Property<string>("$type").ToJsonProperty("Discriminator");

            // Breaking change 2: EF 9 uses only the key for "id" (e.g. "1").
            // Existing documents use "Blog|1" format, so preserve it.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<BlogIdGenerator>();

            // Breaking change 3: Cosmos DB does not support indexes defined via EF.
            // HasIndex() now throws in EF 9; removed.
        });
    }

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        // Breaking change 4: Sync I/O now throws by default in EF 9.
        // Opt back in for SyncJob compatibility.
        options.UseCosmos("<connection-string>", "<database>",
            cosmosOptions => cosmosOptions.AllowSynchronousQueryExecution(true));
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

